import ImgixClient from '@imgix/js-core';

const client = new ImgixClient({
  domain: 'your-company.imgix.net',
  secureURLToken: process.env.IMGIX_TOKEN,
});

// Generate URL for a 800x600 WebP image
const url = client.buildURL('path/to/image.jpg', {
  w: 800,
  h: 600,
  fit: 'crop',
  auto: 'format,compress', // Auto WebP/AVIF + compression
  q: 80,
});

console.log('Transformed URL:', url);
// https://your-company.imgix.net/path/to/image.jpg?w=800&h=600&fit=crop&auto=format%2Ccompress&q=80&s=...

// Generate a srcset for responsive images
const srcSet = client.buildSrcSet('path/to/image.jpg', {
  auto: 'format,compress',
  fit: 'max',
});
console.log('srcSet:', srcSet);
